static FString Encode(TSharedPtr<FJsonObject> J){FString Out;FJsonSerializer::Serialize(J.ToSharedRef(),TJsonWriterFactory<>::Create(&Out));return Out;}
static TSharedPtr<FJsonObject> Body(UStaticMesh* M){auto J=MakeShared<FJsonObject>();if(!M)return J;J->SetStringField(TEXT("asset"),M->GetPathName());if(auto* B=M->GetBodySetup()){J->SetNumberField(TEXT("boxes"),B->AggGeom.BoxElems.Num());J->SetNumberField(TEXT("convexes"),B->AggGeom.ConvexElems.Num());J->SetNumberField(TEXT("spheres"),B->AggGeom.SphereElems.Num());J->SetNumberField(TEXT("capsules"),B->AggGeom.SphylElems.Num());J->SetNumberField(TEXT("complexity_enum"),B->CollisionTraceFlag);TArray<TSharedPtr<FJsonValue>> Rows;for(auto& Box:B->AggGeom.BoxElems){auto X=MakeShared<FJsonObject>();X->SetStringField(TEXT("center"),Box.Center.ToString());X->SetStringField(TEXT("rotation"),Box.Rotation.ToString());X->SetStringField(TEXT("dimensions"),FVector(Box.X,Box.Y,Box.Z).ToString());Rows.Add(MakeShared<FJsonValueObject>(X));}J->SetArrayField(TEXT("box_shapes"),Rows);}return J;}
FString USTCollisionReview::DescribeActor(AActor* A){auto J=MakeShared<FJsonObject>();if(!A)return Encode(J);J->SetStringField(TEXT("actor"),A->GetActorLabel());J->SetStringField(TEXT("class"),A->GetClass()->GetPathName());TArray<TSharedPtr<FJsonValue>> Cs;TArray<UStaticMeshComponent*> Components;A->GetComponents(Components);for(auto* C:Components){auto X=Body(C->GetStaticMesh());X->SetStringField(TEXT("component"),C->GetName());X->SetStringField(TEXT("position"),C->GetComponentLocation().ToString());X->SetStringField(TEXT("scale"),C->GetComponentScale().ToString());X->SetStringField(TEXT("world_bounds"),C->Bounds.GetBox().ToString());X->SetNumberField(TEXT("collision_enabled_enum"),int(C->GetCollisionEnabled()));X->SetNumberField(TEXT("pawn_response_enum"),int(C->GetCollisionResponseToChannel(ECC_Pawn)));X->SetStringField(TEXT("profile"),C->GetCollisionProfileName().ToString());Cs.Add(MakeShared<FJsonValueObject>(X));}J->SetArrayField(TEXT("components"),Cs);return Encode(J);}
FString USTCollisionReview::GenerateStandard(UStaticMesh* M,bool Convex,int32 HullCount){TSharedPtr<FJsonObject> J=MakeShared<FJsonObject>();bool OK=M&&M->GetPathName().StartsWith(TEXT("/Game/F07COLL01/"));if(OK){auto* S=GEditor->GetEditorSubsystem<UStaticMeshEditorSubsystem>();S->RemoveCollisionsWithNotification(M,false);OK=Convex?S->SetConvexDecompositionCollisionsWithNotification(M,HullCount,24,100000,false):S->AddSimpleCollisionsWithNotification(M,EScriptCollisionShapeType::Box,false)>=0;auto* B=M->GetBodySetup();B->CollisionTraceFlag=CTF_UseSimpleAndComplex;B->InvalidatePhysicsData();B->CreatePhysicsMeshes();M->MarkPackageDirty();J=Body(M);}J->SetBoolField(TEXT("ok"),OK);J->SetStringField(TEXT("method"),Convex?TEXT("Unreal StaticMeshEditor Auto Convex Collision"):TEXT("Unreal StaticMeshEditor Add Box Simplified Collision"));return Encode(J);}
bool USTCollisionReview::CopyGeneratedCollision(UStaticMesh* Target,UStaticMesh* Proxy,bool Floor){if(!Target||!Proxy||!Target->GetPathName().StartsWith(TEXT("/Game/F07COLL01/"))||!Proxy->GetPathName().StartsWith(TEXT("/Game/F07COLL01/")))return false;Target->CreateBodySetup();auto* B=Target->GetBodySetup();B->AggGeom=Proxy->GetBodySetup()->AggGeom;for(auto& Box:B->AggGeom.BoxElems){if(Box.X<.2)Box.X=.2;if(Box.Y<.2)Box.Y=.2;if(Box.Z<.2){if(Floor){Box.Center.Z-=.5;Box.Z=1;}else Box.Z=.2;}}B->CollisionTraceFlag=CTF_UseSimpleAndComplex;B->InvalidatePhysicsData();B->CreatePhysicsMeshes();Target->MarkPackageDirty();return B->AggGeom.GetElementCount()>0;}
FString USTCollisionReview::Probe(UObject* Context,FVector Start,FVector End,float Radius,float HalfHeight,AActor* Isolate,bool Complex){auto J=MakeShared<FJsonObject>();auto* W=GEngine->GetWorldFromContextObject(Context,EGetWorldErrorMode::ReturnNull);if(!W)return Encode(J);FCollisionQueryParams Q(SCENE_QUERY_STAT(COLL01),Complex);if(Isolate)for(TActorIterator<AActor> It(W);It;++It)if(*It!=Isolate)Q.AddIgnoredActor(*It);FHitResult H;bool Hit=Radius<=0?W->LineTraceSingleByChannel(H,Start,End,ECC_Pawn,Q):W->SweepSingleByChannel(H,Start,End,FQuat::Identity,ECC_Pawn,HalfHeight>0?FCollisionShape::MakeCapsule(Radius,HalfHeight):FCollisionShape::MakeSphere(Radius),Q);J->SetBoolField(TEXT("hit"),Hit);J->SetBoolField(TEXT("start_penetrating"),H.bStartPenetrating);J->SetNumberField(TEXT("time"),H.Time);J->SetStringField(TEXT("actor"),H.GetActor()?H.GetActor()->GetActorLabel():TEXT("None"));J->SetStringField(TEXT("component"),GetNameSafe(H.GetComponent()));J->SetStringField(TEXT("impact"),H.ImpactPoint.ToString());J->SetStringField(TEXT("normal"),H.ImpactNormal.ToString());return Encode(J);}
